Une hache en bronze, datée de l’âge du Bronze moyen, découverte dans un contexte funéraire.


json_data = {
  "id": "OBJ_001",
  "type": "hache",
  "materiau": "bronze",
  "periode": "Bronze moyen",
  "contexte": "funéraire"
}


import json

objet = json.loads(json_data)

if objet["materiau"] == "bronze":
    print(objet["id"])




